#include <vector>
#include <algorithm>
#include <unordered_map>

class Solution {
public:
    std::vector<int> recoverArray(std::vector<int>& nums) {
        std::sort(nums.begin(), nums.end());
        int total = nums.size();
        int n = total / 2;

        for (int i = 1; i < total; ++i) {
            int diff = nums[i] - nums[0];
            if (diff == 0 || diff % 2 != 0) continue;

            int k = diff / 2;
            std::unordered_map<int, int> counts;
            for (int x : nums) counts[x]++;

            std::vector<int> original;
            for (int x : nums) {
                if (counts[x] == 0) continue;
                if (counts[x + diff] == 0) break;
                counts[x]--;
                counts[x + diff]--;
                original.push_back(x + k);
            }

            if ((int)original.size() == n) return original;
        }
        return {};
    }
};

import java.util.*;

class Solution {
    public int[] recoverArray(int[] nums) {
        Arrays.sort(nums);
        int total = nums.length;
        int n = total / 2;

        for (int i = 1; i < total; i++) {
            int diff = nums[i] - nums[0];
            if (diff == 0 || diff % 2 != 0) continue;

            int k = diff / 2;
            Map<Integer, Integer> counts = new HashMap<>();
            for (int x : nums) counts.put(x, counts.getOrDefault(x, 0) + 1);

            int[] original = new int[n];
            int ptr = 0;

            for (int x : nums) {
                if (counts.get(x) == 0) continue;
                if (counts.getOrDefault(x + diff, 0) == 0) break;

                counts.put(x, counts.get(x) - 1);
                counts.put(x + diff, counts.get(x + diff) - 1);
                original[ptr++] = x + k;
            }

            if (ptr == n) return original;
        }
        return new int[0];
    }
}

