var recoverArray = function(nums) {
    nums.sort((a, b) => a - b);
    const total = nums.length;
    const n = total / 2;

    for (let i = 1; i < total; i++) {
        const diff = nums[i] - nums[0];
        if (diff === 0 || diff % 2 !== 0) continue;

        const k = diff / 2;
        const counts = new Map();
        for (const x of nums) counts.set(x, (counts.get(x) || 0) + 1);

        const original = [];
        for (const x of nums) {
            if (counts.get(x) === 0) continue;
            if (!counts.get(x + diff)) break;

            counts.set(x, counts.get(x) - 1);
            counts.set(x + diff, counts.get(x + diff) - 1);
            original.push(x + k);
        }

        if (original.length === n) return original;
    }
    return [];
};
